/// SafeNexus HSE – Consolidated Master Handbook Topics 01–25
/// Educational reference. Confirm current UAE law, authority requirements,
/// client standards, engineering basis and approved site procedures.
library safenexus_hse_topics_01_25;

class HseTopic {
  final int number;
  final String title;
  final String content;
  const HseTopic({required this.number, required this.title, required this.content});
}

const List<HseTopic> hseTopics01To25 = [
  HseTopic(number: 1, title: 'HSE Management System & UAE HSE Framework', content: 'TOPIC 01 – HSE Management System & UAE HSE Framework\n\nPurpose\nEstablish leadership, policy, planning, implementation, evaluation and improvement arrangements for a functioning HSE management system.\n\nTechnical requirements and field application\n1. Set policy, objectives, responsibilities, resources, consultation, operational control, monitoring, audit and management review.\n2. Integrate HSE into design, procurement, construction, operation, maintenance and decommissioning.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 2, title: 'Legal Compliance, Regulatory Duties & HSE Governance', content: 'TOPIC 02 – Legal Compliance, Regulatory Duties & HSE Governance\n\nPurpose\nIdentify applicable legal, regulator, client and contractual obligations, assign owners and verify compliance using controlled evidence.\n\nTechnical requirements and field application\n1. Maintain a legal and other requirements register with applicability, owner, evidence, review date and change monitoring.\n2. Do not treat guidance or an illustrative handbook as a substitute for current official requirements or client procedures.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 3, title: 'Hazard Identification, Risk Assessment & ALARP', content: 'TOPIC 03 – Hazard Identification, Risk Assessment & ALARP\n\nPurpose\nIdentify hazards, assess risk, apply the hierarchy of controls and confirm residual risk is authorized under the approved process.\n\nTechnical requirements and field application\n1. Use suitable methods such as task risk assessment, JSA/JHA, HAZID, HAZOP or bow-tie according to complexity and lifecycle stage.\n2. Risk matrices support prioritization; they are not precise predictions and must follow approved company criteria.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 4, title: 'Permit to Work & High-Risk Work Authorization', content: 'TOPIC 04 – Permit to Work & High-Risk Work Authorization\n\nPurpose\nControl hazardous work through authorization, coordination, isolation checks, monitoring, suspension and formal handback.\n\nTechnical requirements and field application\n1. Define permit scope, validity, isolations, gas testing, simultaneous operations, handover, suspension and closeout.\n2. A permit does not itself make work safe; field verification and supervision remain essential.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 5, title: 'Lockout/Tagout, Isolation & Energy Control', content: 'TOPIC 05 – Lockout/Tagout, Isolation & Energy Control\n\nPurpose\nPrevent unexpected energization, release of stored energy or hazardous movement through verified isolation and controlled restoration.\n\nTechnical requirements and field application\n1. Identify all energy sources, isolate, lock/tag, dissipate stored energy, prove zero energy and control group/shift handover.\n2. Test-before-touch and independent verification should follow approved electrical and isolation procedures.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 6, title: 'Working at Height & Fall Prevention', content: 'TOPIC 06 – Working at Height & Fall Prevention\n\nPurpose\nPrevent falls and dropped objects through suitable access, edge protection, equipment, supervision and credible rescue arrangements.\n\nTechnical requirements and field application\n1. Prioritize collective protection such as guardrails and safe platforms; select fall-arrest only with suitable anchorage and rescue plan.\n2. Inspect harnesses and connectors, control dropped objects and prevent unauthorized alteration of access systems.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 7, title: 'Scaffolding, Access Equipment & Temporary Platforms', content: 'TOPIC 07 – Scaffolding, Access Equipment & Temporary Platforms\n\nPurpose\nEnsure scaffold and access systems are designed, erected, inspected, altered and dismantled by competent authorized personnel.\n\nTechnical requirements and field application\n1. Verify foundation, load class, ties, bracing, access, platform integrity, tagging and inspection status.\n2. Never use incomplete, altered or untagged scaffolds unless formally controlled under an approved system.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 8, title: 'Lifting Operations, Rigging & Crane Safety', content: 'TOPIC 08 – Lifting Operations, Rigging & Crane Safety\n\nPurpose\nPlan and execute lifting operations with verified equipment, competent roles, load control, exclusion zones and communication.\n\nTechnical requirements and field application\n1. Prepare lift plan, load data, radius, ground bearing, crane configuration, rigging capacity, weather limits and communication.\n2. Establish exclusion zones and stop if visibility, stability, load control or communication is lost.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 9, title: 'Confined Space Entry & Rescue', content: 'TOPIC 09 – Confined Space Entry & Rescue\n\nPurpose\nPrevent engulfment, asphyxiation, toxic exposure and other confined-space harm through entry control, testing, isolation and rescue readiness.\n\nTechnical requirements and field application\n1. Identify space hazards, isolate connected systems, test atmosphere using approved sequence, ventilate and maintain communications.\n2. Rescue must be planned and resourced; prohibit unplanned entry rescue.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 10, title: 'Excavation, Trenching & Underground Services', content: 'TOPIC 10 – Excavation, Trenching & Underground Services\n\nPurpose\nPrevent collapse, utility strikes, falls and water ingress through excavation planning, service locating, support, access and inspection.\n\nTechnical requirements and field application\n1. Obtain utility drawings and locate services, use trial holes where required, assess ground and water, provide safe access and spoil setbacks.\n2. Inspect after change in conditions and keep people/equipment clear of unsupported edges.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 11, title: 'Electrical Safety, Temporary Power & Portable Tools', content: 'TOPIC 11 – Electrical Safety, Temporary Power & Portable Tools\n\nPurpose\nPrevent shock, arc flash, fire and tool-related injury through safe design, inspection, isolation, grounding and competent work.\n\nTechnical requirements and field application\n1. Verify competent authorization, equipment condition, protective devices, cable routing, environmental suitability and isolation.\n2. Electrical test methods and inspection intervals must follow applicable standards and site procedures.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedure and competent-person requirements before work. The examples in this handbook are educational and do not replace engineering approval or legal advice.\n\nInterview questions\n1. Explain the purpose and principal hazards addressed by this topic.\n2. What evidence would you check before authorizing or accepting the work?\n3. What would make you stop work, escalate and reassess?\n4. How would you verify that corrective actions are effective?\n\nPractical assessment\nDescribe a realistic site task related to this topic. Identify hazards, exposed persons, critical controls, verification evidence, emergency response and restart authorization.\n'),
  HseTopic(number: 12, title: 'Pressure Relief Systems, Overpressure Protection & Flare System Integrity', content: 'TOPIC 12 – Pressure Relief Systems, Overpressure Protection & Flare System Integrity\n\nPurpose\nProvide systematic controls for pressure relief systems, overpressure protection & flare system integrity in UAE workplaces and projects.\n\nTechnical requirements and field application\n1. Use approved company standards, risk assessments and task-specific procedures; verify current jurisdiction and client requirements.\n2. Define performance criteria, competent roles, inspection evidence, escalation triggers and emergency arrangements.\n3. Define scope, roles, applicable requirements and acceptance criteria before work begins.\n4. Identify routine, non-routine, abnormal and emergency conditions; include workers, contractors and affected interfaces.\n5. Apply elimination and substitution first, then engineering controls, administrative controls and PPE as the final layer.\n6. Use competent personnel, approved procedures, suitable equipment and documented authorization where required.\n7. Inspect controls before use and at risk-based intervals; remove defective equipment from service and record disposition.\n8. Stop work and reassess when scope, conditions, personnel, equipment, weather or interfaces change.\n9. Record evidence, communicate deficiencies, assign accountable owners and verify effectiveness before closure.\n\nField records and verification\n- Maintain a controlled register identifying the activity/equipment, location, responsible owner, inspection or review date, status, deficiencies and closeout evidence.\n- Verify controls in the field rather than relying only on signatures or document completion.\n- Record deviations, immediate safeguards, corrective action owner, due date and effectiveness check.\n\nUAE application\nApply the current requirements of the relevant UAE authority, emirate, client and operator. Confirm the approved site procedu